    'Empty. Hit a card’s “✓ In use” (or “Store all”) to park templates here — they stay in your library but stop showing when you make Shots.': '비어 있습니다. 카드의 ‘✓ 사용 중’(또는 ‘전부 보관’)을 눌러 여기에 보관하세요 — 라이브러리에는 남고 고를 때만 안 뜹니다.',
