    'Put your product on a photorealistic model. Choose the model and setting, then get on-model catalog shots from a single photo.': '제품을 실사 모델에게 입혀 드려요. 모델과 배경만 고르면 사진 한 장으로 온모델 카탈로그 컷이 나와요.',
