    'Same motion, new product — lit with the scene\'s light. Open it in the Video Editor to trim, add text or music.': '같은 움직임, 새 제품 — 장면의 빛으로 조명됩니다. 영상 편집기에서 열어 자르고 텍스트·음악을 넣으세요.',
