    'The hard part — prompt engineering, lighting, consistency — is baked into every template. You just choose.': '難しい部分 — プロンプト設計、ライティング、一貫性 — はすべてのテンプレートに組み込み済み。選ぶだけです。',
    'One product photo — any angle. We remove the background and lock the product so it stays true across every frame.': 'どの角度でも商品写真1枚。背景を削除して商品を固定し、すべてのフレームで同じに保ちます。',
    'Browse curated looks and trending reel formats for your industry. Filter by style — no prompt writing, no settings to fiddle with.': '業種に合わせたルックとトレンドのリール形式を閲覧。スタイルで絞り込み — プロンプトも設定いじりも不要。',
    'Get a full set of product photos or a ready reel in seconds. Download, or publish straight to Instagram.': '数秒で商品写真セットや完成リールを。ダウンロードするか、Instagramに直接投稿。',
    'Every shot your store needs — from one photo': 'ストアに必要なすべてのショット — 写真1枚から',
    'Whatever you sell, the same template magic turns a single product shot into a full campaign.': '何を売っていても、同じテンプレートの魔法が商品写真1枚をキャンペーン一式に変えます。',
    'Studio-grade shots, no studio': 'スタジオなしで、スタジオ品質',
    'Drop in one product photo — fashion, beauty, food, home, tech, pet and more — and get lookbooks, lifestyle scenes and on-model shots. Background removed automatically.': '商品写真を1枚入れるだけ — ファッション・ビューティー・フード・ホーム・テック・ペットなど — ルックブック、ライフスタイルシーン、モデル着用ショットが手に入ります。背景は自動で削除。',
