    'Tap a template below — the look is applied to your product instantly. Filter by category (Apparel, Beauty…). No prompt needed.': '下のテンプレートをタップすると、そのルックが商品にすぐ適用されます。カテゴリ (アパレル・ビューティーなど) で絞り込み。プロンプトは不要。',
