    'Turn a Custom creation into a template': 'カスタム作品をテンプレートに',
    'In Your creations, click + Create template under any Custom creation — an image or reel you made from your own prompt. (Template-based creations already have a template.)': '「マイ作品」で、自分のプロンプトで作ったカスタム作品 (画像またはリール) の下の「＋ テンプレートを作成」を押します。(テンプレートから作った作品にはすでにテンプレートがあります。)',
